"""Own component-ablation runner/reviewer; keep both old controls immutable."""
from pathlib import Path
import sys
sys.path[:0] = [str(Path(__file__).resolve().parents[1]/'src'),str(Path(__file__).resolve().parent)]
from jmicro.experiment import ROOT
from prepare_eos_decoupled_web_kl import once,write


def main():
    runner = (ROOT/'scripts/run_web_kl_comparison_v3.py').read_text()
    runner = runner.replace('from resident_web_kl_trainer import','from eos_decoupled_resident_web_kl_trainer import')
    runner = runner.replace('from web_kl_preservation import POLICY','from eos_decoupled_web_kl_preservation import POLICY')
    runner = runner.replace('web-kl-comparison-v3-20261006','eos-decoupled-web-kl-comparison-20261006')
    runner = runner.replace('web_kl_comparison_v3','eos_decoupled_web_kl_comparison').replace('web_kl_probe_v3','eos_decoupled_web_kl_probe')
    runner = runner.replace('prepare_web_kl_content_review_v3','prepare_eos_decoupled_web_kl_content_review')
    runner = runner.replace("'reports/phase6/web_kl_comparison_proposal.json'","'reports/phase6/eos_decoupled_web_kl_comparison_proposal.json'")
    runner = runner.replace("'reports/phase6/web_kl_trainer_preparation.json'","'reports/phase6/eos_decoupled_web_kl_trainer_preparation.json'")
    runner = once(runner,"ARM='web_kl'","ARM='eos_decoupled_web_kl'\nMECHANISM_RUN=ROOT/'reports/phase6/web-kl-comparison-v3-20261006'\nQUALITY_BASELINE='cached-staged-CE23-EOS76-repetition2-all-original-gates'")
    runner = once(runner,"PRIOR_GPU=read_json(RESIDENT_PROPOSAL)['prior_probe_GPU_seconds']","PRIOR_GPU=0. # No GPU work for this distinct, newly frozen objective-component study yet.")
    runner = once(runner,"SOURCES=tuple(dict.fromkeys((", "SOURCES=tuple(dict.fromkeys(('scripts/implement_eos_decoupled_web_kl_comparison.py',\n    'scripts/eos_decoupled_web_kl_preservation.py','scripts/eos_decoupled_web_kl_condition_trainer.py',\n    'scripts/eos_decoupled_resident_web_kl_trainer.py','scripts/eos_decoupled_web_kl_accounting.py',\n    'tests/test_eos_decoupled_web_kl_preservation.py','tests/test_eos_decoupled_web_kl_condition_trainer.py',\n    'scripts/prepare_eos_decoupled_web_kl.py','scripts/propose_eos_decoupled_web_kl_comparison.py',")
    runner = once(runner,"performance['prior_probe_GPU_seconds']!=PRIOR_GPU", "performance['prior_probe_GPU_seconds']!=read_json(FAILED_PROBE)['actual_GPU_seconds']+read_json(Path(performance['prior_successful_probe']['path']))['GPU_seconds']")
    runner = once(runner,"    preparation=ROOT/", "    for ref in p['mechanism_full_KL'].values():check_reference(ref)\n    full_job=read_json(MECHANISM_RUN/'job.json')\n    full_result=read_json(MECHANISM_RUN/'compare-result.json')\n    full_review=read_json(Path(p['mechanism_full_KL']['review']['path']))\n    if (full_job['status']!='complete' or alive(full_job) or full_review['result_sha256']!=p['mechanism_full_KL']['result']['sha256']\n            or full_result['checkpoints']['web_kl']['additional_supervised_tokens']!=TOTAL\n            or p['previous_related_study_all_GPU_seconds']!=read_json(Path(p['previous_related_completed_study']['path']))['all_GPU_seconds']):\n        raise ValueError('Actual complete fullKL mechanism control required')\n    preparation=ROOT/")
    runner = once(runner,"        GPU_budget_seconds=120,", "        quality_screen_baseline=QUALITY_BASELINE,previous_related_study_GPU_seconds=p['previous_related_study_all_GPU_seconds'],\n        GPU_budget_seconds=120,")
    runner = once(runner,"    scope(c);atomic_json(PROBE_CONFIG,c);", "    c['references'].update({'mechanism_'+k:v for k,v in p['mechanism_full_KL'].items()})\n    scope(c);atomic_json(PROBE_CONFIG,c);")
    runner = once(runner,"    if (c['KL_policy']!=POLICY", "    if (c['quality_screen_baseline']!=QUALITY_BASELINE or c['KL_policy']!=POLICY")
    runner = once(runner,"reference_inputs=reference_positions=0", "reference_inputs=reference_positions=0\n    reference_mass=0.")
    runner = once(runner,"        reference_inputs+=trainer.replay.physical_input_tokens;", "        reference_mass+=trainer.reference_non_EOS_teacher_mass\n        reference_inputs+=trainer.replay.physical_input_tokens;")
    runner = once(runner,"                'reference_input_tokens', 'reference_soft_target_body_positions',", "                'reference_non_EOS_teacher_probability_mass','reference_input_tokens', 'reference_soft_target_body_positions',")
    runner = once(runner,"        GPU_optimizer_updates=8,", "        verification_reference_non_EOS_teacher_probability_mass=reference_mass,GPU_optimizer_updates=8,")
    runner = once(runner,"    previous=read_json(Path(read_json(RESIDENT_PROPOSAL)['prior_successful_probe']['path']))", "    previous=read_json(MECHANISM_RUN/'probe/result.json')")
    runner = once(runner,"    keys=('loss','ordinary_CE_loss','reference_KL_loss','gradient_norm','lr','token_digest'", "    keys=('lr','token_digest'")
    runner = runner.replace('Resident reader changed actual update trajectory','New objective changed actual main/reference input protocol')
    runner = once(runner,"                    reference_input_tokens=trainer.replay.physical_input_tokens,reference_soft_positions=trainer.replay.body_positions)", "                    reference_non_EOS_teacher_probability_mass=trainer.reference_non_EOS_teacher_mass,\n                    reference_input_tokens=trainer.replay.physical_input_tokens,reference_soft_positions=trainer.replay.body_positions)")
    runner = once(runner,"                    verification_reference_input_tokens=gate['verification_reference_input_tokens']", "                    verification_reference_non_EOS_teacher_probability_mass=gate['verification_reference_non_EOS_teacher_probability_mass']+timing['reference_non_EOS_teacher_probability_mass'],\n                    verification_reference_input_tokens=gate['verification_reference_input_tokens']")
    runner = once(runner,"                or c['verification_reference_input_tokens']!=", "                or c['verification_reference_non_EOS_teacher_probability_mass']!=measured['verification_reference_non_EOS_teacher_probability_mass']\n                or c['verification_reference_input_tokens']!=")
    runner = once(runner,"        verification_reference_input_tokens=r['verification_reference_input_tokens']", "        verification_reference_non_EOS_teacher_probability_mass=r['verification_reference_non_EOS_teacher_probability_mass'],\n        verification_reference_input_tokens=r['verification_reference_input_tokens']")
    runner = once(runner,"                if result['checkpoints']['control']!=control", "                old_full=read_json(MECHANISM_RUN/'compare-result.json')\n                mechanism_cached={k:old_full[k]['web_kl'] for k in ('checkpoints','evaluations','transfer','retention')}\n                result.setdefault('mechanism_cached',mechanism_cached)\n                if result['mechanism_cached']!=mechanism_cached:raise ValueError('Cached fullKL mechanism evidence differs')\n                if result['checkpoints']['control']!=control")
    runner = once(runner,"                    result['checkpoints'][ARM].update(reference_replay=", "                    result['checkpoints'][ARM].update(reference_non_EOS_teacher_probability_mass=trainer.reference_non_EOS_teacher_mass,reference_replay=")
    runner = once(runner,"                    reference_input_tokens=result['checkpoints'][ARM]['reference_input_tokens']", "                    reference_non_EOS_teacher_probability_mass=result['checkpoints'][ARM]['reference_non_EOS_teacher_probability_mass'],\n                    previous_related_study_GPU_seconds=c['previous_related_study_GPU_seconds'],quality_screen_baseline=QUALITY_BASELINE,\n                    mechanism_comparison_teacher_tokens=2*TOTAL,reference_input_tokens=result['checkpoints'][ARM]['reference_input_tokens']")
    write('scripts/run_eos_decoupled_web_kl_comparison.py',runner)
    ps = (ROOT/'scripts/run_web_kl_comparison_v3.ps1').read_text()
    ps = ps.replace('web-kl-v3-','eos-decoupled-web-kl-').replace('web-kl-comparison-v3-','eos-decoupled-web-kl-comparison-')
    ps = ps.replace('run_web_kl_comparison_v3.py','run_eos_decoupled_web_kl_comparison.py')
    write('scripts/run_eos_decoupled_web_kl_comparison.ps1',ps)
    accountant = (ROOT/'scripts/web_kl_comparison_accounting.py').read_text().replace('from web_kl_preservation import POLICY','from eos_decoupled_web_kl_preservation import POLICY')
    accountant = once(accountant,"    return dict(frozen_parent_teacher_digest_verified=", "    mass=extra['non_EOS_teacher_probability_mass']\n    if not 0<mass<=replay['body_positions'] or mass!=record['reference_non_EOS_teacher_probability_mass'] or mass!=history[-1]['reference_non_EOS_teacher_probability_mass']:\n        raise ValueError('Terminal retained probability-mass ledger differs')\n    previous_mass=0.;previous_positions=0\n    for row in history:\n        increment=row['reference_non_EOS_teacher_probability_mass']-previous_mass\n        positions=row['reference_soft_target_body_positions']-previous_positions\n        if not 0<increment<=positions+1e-3:raise ValueError('Retained per-update target probability mass differs')\n        previous_mass=row['reference_non_EOS_teacher_probability_mass'];previous_positions=row['reference_soft_target_body_positions']\n    return dict(reference_non_EOS_teacher_probability_mass=mass,frozen_parent_teacher_digest_verified=")
    write('scripts/eos_decoupled_web_kl_accounting.py',accountant)
    reviewer = (ROOT/'scripts/review_web_kl_comparison_v3.py').read_text().replace('run_web_kl_comparison_v3','run_eos_decoupled_web_kl_comparison')
    reviewer = reviewer.replace('from web_kl_comparison_accounting import','from eos_decoupled_web_kl_accounting import')
    reviewer = reviewer.replace('web_kl_notes.json','eos_decoupled_web_kl_notes.json').replace('web_kl_comparison_v3_review.json','eos_decoupled_web_kl_comparison_review.json')
    reviewer = once(reviewer,"    del state, previous_state", "    full_result=read_json(study.MECHANISM_RUN/'compare-result.json')\n    expected_cached={k:full_result[k]['web_kl'] for k in ('checkpoints','evaluations','transfer','retention')}\n    if r['mechanism_cached']!=expected_cached:raise ValueError('Exact fullKL mechanism cache differs')\n    full_record=expected_cached['checkpoints'];full_state=torch.load(full_record['checkpoint'],map_location='cpu',weights_only=False)\n    retained_sources(parent,state,full_state)\n    full_history=[json.loads(s) for s in (study.MECHANISM_RUN/'web_kl/training/metrics.jsonl').read_text().splitlines()]\n    keys=('token_digest','source_teachers','source_eos','source_input_tokens','source_body_bytes','source_focus_teachers',\n        'reference_input_tokens','reference_soft_target_body_positions','reference_ignored_positions','reference_digest','combined_student_physical_input_tokens')\n    if len(history)!=3068 or len(full_history)!=3068 or any(not equal_state(a[k],b[k]) for a,b in zip(history,full_history,strict=True) for k in keys):\n        raise ValueError('All3068 same CE/reference input protocols required')\n    del state, previous_state,full_state")
    reviewer = once(reviewer,"    s = summaries[study.ARM]", "    full_raw=study.MECHANISM_RUN/'evaluation/web_kl/evaluation/generation.json'\n    full_notes=ROOT/'reports/phase6/web_kl_notes.json'\n    full_ev=expected_cached['evaluations']\n    if read_json(full_raw)!=full_ev['generation']:raise ValueError('Cached fullKL raw generation differs')\n    full_scores=validate_notes(full_ev['generation']['outputs'],read_json(full_notes),sha256(full_raw))\n    mechanism=quality_gates(full_ev,r['evaluations'][study.ARM],full_scores,scores[study.ARM],'content')\n    s = summaries[study.ARM]")
    reviewer = once(reviewer,"        summaries=summaries, primary_comparison=", "        quality_screen_baseline=study.QUALITY_BASELINE,mechanism_comparison=mechanism,\n        mechanism_summary=read_json(ROOT/'reports/phase6/web_kl_comparison_v3_review.json')['summaries']['web_kl'],\n        all3068_main_and_reference_input_protocols_equal=True,previous_related_study_GPU_seconds=c['previous_related_study_GPU_seconds'],\n        summaries=summaries, primary_comparison=")
    reviewer = once(reviewer,"        verification_reference_input_tokens=probe['verification_reference_input_tokens']", "        verification_reference_non_EOS_teacher_probability_mass=probe['verification_reference_non_EOS_teacher_probability_mass'],\n        verification_reference_input_tokens=probe['verification_reference_input_tokens']")
    write('scripts/review_eos_decoupled_web_kl_comparison.py',reviewer)
    content = (ROOT/'scripts/prepare_web_kl_content_review_v3.py').read_text().replace('run_web_kl_comparison_v3','run_eos_decoupled_web_kl_comparison').replace("ROOT / 'reports/phase6/web_kl_notes.json'","ROOT / 'reports/phase6/eos_decoupled_web_kl_notes.json'")
    content = once(content,"    stage_notes=ROOT/", "    full_raw=study.MECHANISM_RUN/'evaluation/web_kl/evaluation/generation.json'\n    full_notes=ROOT/'reports/phase6/web_kl_notes.json'\n    generation,notes=read_json(full_raw),read_json(full_notes)\n    validate_notes(generation['outputs'],notes,sha256(full_raw))\n    indexed={n[0]:n for n in notes['notes']}\n    for row in generation['outputs']:\n        k=key(row);note=indexed[row['id']]\n        if k in saved and saved[k]!=note:raise ValueError('Conflicting exact fullKL peer')\n        saved[k]=note\n    refs.append(dict(notes=study.reference(full_notes),generation=study.reference(full_raw)))\n    stage_notes=ROOT/")
    write('scripts/prepare_eos_decoupled_web_kl_content_review.py',content)
    test = (ROOT/'tests/test_web_kl_comparison_v3.py').read_text().replace('run_web_kl_comparison_v3','run_eos_decoupled_web_kl_comparison')
    test = test.replace('from web_kl_comparison_accounting import','from eos_decoupled_web_kl_accounting import')
    test = test.replace('from web_kl_preservation import POLICY','from eos_decoupled_web_kl_preservation import POLICY')
    test = once(test,'    c=dict(KL_policy=POLICY,', '    c=dict(quality_screen_baseline=study.QUALITY_BASELINE,KL_policy=POLICY,')
    test = once(test,"    for key,value in (('KL_policy'", "    for key,value in (('quality_screen_baseline','poorer-fullKL-control'),('KL_policy'")
    test = once(test,'KL_state=dict(policy=POLICY,', 'KL_state=dict(non_EOS_teacher_probability_mass=15999.,policy=POLICY,')
    test = once(test,'    record=dict(KL_policy=POLICY,','    record=dict(reference_non_EOS_teacher_probability_mass=15999.,KL_policy=POLICY,')
    test = once(test,'    history=[dict(reference_input_tokens=i*8192,','    history=[dict(reference_non_EOS_teacher_probability_mass=i*7999.5,reference_input_tokens=i*8192,')
    test = once(test,"    bad=copy.deepcopy(record);bad['reference_input_tokens']=0", "    bad=copy.deepcopy(record);bad['reference_non_EOS_teacher_probability_mass']=0\n    with pytest.raises(ValueError):audit_reference(parent,state,bad,history,config)\n    bad=copy.deepcopy(record);bad['reference_input_tokens']=0")
    write('tests/test_eos_decoupled_web_kl_comparison.py',test)
    print('Own runner/reviewer and probability-mass accounting generated; strong staged quality control retained')


if __name__ == '__main__':
    if sys.version_info[:3] != (3,12,7):
        raise RuntimeError('Pinned uv Python3.12.7 required')
    main()
